];

function editableSteps(content: FunnelStepPages): Steps {
  return content.flow.steps.filter((step) => !step.isSystem).map(({ id, name, path }) => ({ id, name, path }));
}

// One management surface coordinates the seven tabs and atomic step actions;
// splitting its state across sibling owners would make revision conflicts harder to guard.
// eslint-disable-next-line complexity
export function FunnelOperationsPanel({ initial, initialStepId, csrfName, csrfToken }: { initial: FunnelOperationsEditor; initialStepId: string; csrfName: string; csrfToken: string }) {
  const router = useRouter();
  const initialContent = { ...initial.content, activeStepId: initialStepId };
  const [editor, setEditor] = useState(initial);
  const [mobileStepsOpen, setMobileStepsOpen] = useState(false);
  const [content, setContent] = useState<FunnelStepPages>(initialContent);
  const [reports, setReports] = useState<FunnelReports | null>(null);
  const [reportError, setReportError] = useState(false);
  const [reportRequest, setReportRequest] = useState(0);
  const [tab, setTab] = useState<Tab>("Configuration");
  const [dirty, setDirty] = useState(false);
  const [message, setMessage] = useState("");
  const [settingsOpen, setSettingsOpen] = useState(false);
  const [addOpen, setAddOpen] = useState(false);
  const [changeTemplate, setChangeTemplate] = useState(false);
  const [newStepName, setNewStepName] = useState("新步驟");
  const [newStepPath, setNewStepPath] = useState("new-step");
  const [newStepType, setNewStepType] = useState<EditableStepType>(initial.content.flow.goal === "sell" ? "sales_page" : initial.content.flow.goal === "audience" ? "opt_in_page" : initial.content.flow.goal === "webinar" ? "webinar_registration_page" : "info_page");
  const [newStepSource, setNewStepSource] = useState<"blank" | "template">("template");
  const [newTemplateId, setNewTemplateId] = useState("");
  const [selectedTemplateId, setSelectedTemplateId] = useState("");
  const [pending, setPending] = useState(false);
  const revisionRef = useRef(initial.revision);
  const reportGeneration = useRef(0);
  const inFlight = useRef(false);
  const active = getActiveFunnelStepPage(content);
  const activeStepType = active?.step.type;
  const templates = activeStepType ? listFunnelTemplateGallery(content.flow.goal, activeStepType) : [];
  const newTemplates = listFunnelTemplateGallery(content.flow.goal, newStepType);
  const effectiveSelectedTemplateId = templates.some((item) => item.id === selectedTemplateId)
    ? selectedTemplateId
    : active?.step.template.templateId ?? templates[0]?.id ?? "";
  const effectiveNewTemplateId = newTemplates.some((item) => item.id === newTemplateId)
    ? newTemplateId
    : newTemplates[0]?.id ?? "";
  const needsTemplate = Boolean(active && !active.step.isSystem && active.step.template.source === "template" && !active.step.template.templateId);
  const secondaryDisabled = !active || active.step.isSystem || needsTemplate;

  useEffect(() => {
    if (!dirty) return;
    const guard = (event: BeforeUnloadEvent) => { event.preventDefault(); };
    window.addEventListener("beforeunload", guard);
    return () => window.removeEventListener("beforeunload", guard);
  }, [dirty]);

  useEffect(() => {
    // Reports may be slow; fetch them independently of the editor and server actions.
    const controller = new AbortController();
    const generation = ++reportGeneration.current;
    void fetch(`/api/funnel/operations/reports?pageId=${encodeURIComponent(initial.pageId)}`, {
      cache: "no-store", credentials: "same-origin", signal: controller.signal,
    }).then(async (response) => {
      if (!response.ok || !response.headers.get("content-type")?.includes("application/json")) throw new Error("REPORT_UNAVAILABLE");
      return await response.json() as FunnelReports;
    }).then((loaded) => {
      if (generation === reportGeneration.current) setReports(loaded);
    }).catch(() => {
      if (!controller.signal.aborted && generation === reportGeneration.current) setReportError(true);
    });
    return () => controller.abort();
  }, [initial.pageId, reportRequest]);

  function change(patch: Partial<SettingsState>) { setEditor((value) => ({ ...value, ...patch })); setDirty(true); }
  function operations(next: FunnelOperations) { change({ operations: next }); }
  function runPending(task: () => Promise<void>) {
    setPending(true);
    void task().finally(() => setPending(false));
  }
  function navigate(href: string) {
    if (pending || inFlight.current) return;
    if (dirty && !window.confirm("尚有未儲存的設定，確定離開？")) return;
    router.push(href);
  }
  function selectStep(stepId: string) {
    if (dirty && !window.confirm("切換步驟會捨棄尚未儲存的欄位變更，確定繼續？")) return;
    const result = switchFunnelStep(content, stepId);
    if (!result.ok) { setMessage(result.error); return; }
    setContent(result.state); setDirty(false); setTab("Configuration"); setChangeTemplate(false);
    window.history.replaceState(null, "", `/landing-pages/${editor.pageId}/operations?step=${encodeURIComponent(stepId)}&tab=configuration`);
  }
  function persistContent(next: FunnelStepPages, successMessage: string) {
    setContent(next); setDirty(true);
    if (inFlight.current) { setMessage("前一個變更仍在儲存，請稍候再試。"); return; }
    inFlight.current = true;
    const data = new FormData();
    data.set(csrfName, csrfToken); data.set("operation", "save"); data.set("id", editor.pageId);
    data.set("revision", String(revisionRef.current)); data.set("name", editor.name); data.set("slug", editor.slug);
    data.set("formId", editor.formId ?? ""); data.set("liveId", editor.liveId ?? ""); data.set("content", JSON.stringify(next));
    runPending(async () => {
      try {
        const result = await landingPageAction({ status: "success", message: "" }, data);
        setMessage(result.status === "success" ? successMessage : result.message);
        if (result.status === "success" && result.revision) {
          revisionRef.current = result.revision;
          setEditor((value) => ({ ...value, revision: result.revision!, content: next, steps: editableSteps(next) }));
          setDirty(false);
        }
      } catch { setMessage("連線中斷，變更仍保留在畫面，請稍後重試。"); }
      finally { inFlight.current = false; }
    });
  }
  function reload() {
    if (dirty && !window.confirm("重新載入會捨棄這次尚未儲存的設定，確定繼續？")) return;
    runPending(async () => {
      try {
        const loaded = await readFunnelOperations(editor.pageId);
        revisionRef.current = loaded.revision;
        reportGeneration.current++;
        setEditor(loaded); setContent(loaded.content); setReports(null); setReportError(false); setReportRequest((value) => value + 1); setDirty(false); setMessage("已重新載入最新版本。");
      } catch { setMessage("無法重新載入，請稍後再試。"); }
    });
  }
  function saveSettings() {
    if (inFlight.current) return;
    inFlight.current = true;
    // Clear the previous success before a new save, so the UI cannot report a
    // stale success while this revision is still in flight.
    setMessage("");
    runPending(async () => {
      try {
        const data = new FormData(); data.set(csrfName, csrfToken);
        data.set("settings", JSON.stringify({ pageId: editor.pageId, revision: revisionRef.current, name: editor.name, slug: editor.slug, currency: editor.currency, operations: editor.operations }));
        const result = await updateFunnelOperations(data);
        setMessage(result.message);
        if (result.ok) {
          revisionRef.current = result.revision;
          setEditor((value) => ({ ...value, revision: result.revision, content: { ...content, flow: { ...content.flow, name: value.name, domain: value.slug, currency: value.currency } } }));
          setContent((value) => ({ ...value, flow: { ...value.flow, name: editor.name, domain: editor.slug, currency: editor.currency } }));
          setDirty(false); setSettingsOpen(false);
          reportGeneration.current++;
          setReports(null); setReportError(false); setReportRequest((value) => value + 1);
        }
      } finally { inFlight.current = false; }
    });
  }
  function applyTemplate(templateId: string) {
    if (!active || active.step.isSystem) return;
    if (active.step.template.templateId && !window.confirm("更換模板會取代目前步驟的頁面內容，確定繼續？")) return;
    const result = replaceFunnelStepPage(content, active.step.id, instantiateFunnelTemplate(templateId, active.page.id), templateId);
    if (!result.ok) { setMessage(result.error); return; }
    setChangeTemplate(false); persistContent(result.state, "模板已套用；現在可進入 Edit Page 編輯內容。");
  }
  function saveActiveMetadata() {
    if (!active || active.step.isSystem) return;
    const renamed = renameFunnelStepPage(content, active.step.id, active.step.name);
    if (!renamed.ok) { setMessage(renamed.error); return; }
    const pathed = setFunnelStepPathPage(renamed.state, active.step.id, active.step.path);
    if (!pathed.ok) { setMessage(pathed.error); return; }
    persistContent(pathed.state, "步驟設定已自動儲存。");
  }
  function addStep() {
    const ordinal = content.flow.steps.filter((step) => !step.isSystem).length + 1;
    const input = { id: `step_${crypto.randomUUID().replace(/-/gu, "").slice(0, 24)}`, name: newStepName.trim(), path: newStepPath.trim() || `step-${ordinal}`, type: newStepType, templateSource: newStepSource, ...(newStepSource === "template" && effectiveNewTemplateId ? { templateId: effectiveNewTemplateId } : {}) } as const;
    const added = addFunnelStepPage(content, input);
    if (!added.ok) { setMessage(added.error); return; }
    const created = added.state.flow.steps.find((step) => !content.flow.steps.some((existing) => existing.id === step.id));
    if (!created) return;
    let next = added.state;
    if (newStepSource === "template" && effectiveNewTemplateId) {
      const page = next.pages[created.id];
      if (!page) return;
      const replaced = replaceFunnelStepPage(next, created.id, instantiateFunnelTemplate(effectiveNewTemplateId, page.id), effectiveNewTemplateId);
      if (!replaced.ok) { setMessage(replaced.error); return; }
      next = replaced.state;
    }
    const selected = switchFunnelStep(next, created.id);
    if (selected.ok) next = selected.state;
    setAddOpen(false); setTab("Configuration");
    window.history.replaceState(null, "", `/landing-pages/${editor.pageId}/operations?step=${encodeURIComponent(created.id)}&tab=configuration`);
    persistContent(next, "新步驟已建立。");
  }

  return <section aria-label="一頁式網站管理" className="min-w-0 space-y-2 lg:space-y-4">
    <header className="flex flex-wrap items-center justify-between gap-2 rounded-2xl border border-slate-200 bg-white px-3 py-2 shadow-sm lg:gap-4 lg:px-5 lg:py-4">
      <div className="min-w-0"><p className="text-xs font-semibold text-slate-600"><Link href="/landing-pages" className="hover:text-blue-700">一頁式網站</Link> <span aria-hidden>›</span> {editor.name}</p><h1 className="mt-1 truncate text-2xl font-bold text-slate-950">{editor.name}</h1><p className="mt-1 text-sm text-slate-600">{funnelGoalLabels[content.flow.goal]} · 版本 {editor.revision}</p></div>
      <div className="flex flex-wrap gap-2"><Link href={`/lp/${editor.slug}`} target="_blank" className="inline-flex min-h-10 cursor-pointer items-center gap-2 rounded-lg bg-blue-700 px-4 py-2 text-sm font-bold text-white transition-colors hover:bg-blue-800"><Eye size={17} />查看網站</Link><button type="button" onClick={() => setSettingsOpen(true)} className="inline-flex min-h-10 cursor-pointer items-center gap-2 rounded-lg bg-blue-700 px-4 py-2 text-sm font-bold text-white transition-colors hover:bg-blue-800"><Settings size={17} />網站設定</button></div>
    </header>
    <div className="grid min-h-[70dvh] overflow-hidden rounded-2xl border border-slate-200 bg-white shadow-sm lg:h-[calc(100dvh-13rem)] lg:min-h-[36rem] lg:grid-cols-[18rem_minmax(0,1fr)]">
      <aside aria-label="網站步驟" className="flex min-h-0 flex-col border-b border-slate-200 bg-white lg:border-r lg:border-b-0">
        <button type="button" aria-expanded={mobileStepsOpen} onClick={() => setMobileStepsOpen((open) => !open)} className="min-h-11 px-4 py-2 text-left text-sm font-semibold text-slate-900 focus-visible:ring-2 focus-visible:ring-blue-700 lg:hidden">網站步驟：{active?.step.name ?? "選擇步驟"}（{mobileStepsOpen ? "收合" : "展開"}）</button>
        <div className={`${mobileStepsOpen ? "flex" : "hidden"} min-h-0 flex-col lg:flex`}>
        <div className="max-h-60 min-h-0 flex-1 divide-y divide-slate-100 overflow-auto lg:max-h-none">{content.flow.steps.map((step, index) => <article key={step.id} className={content.activeStepId === step.id ? "bg-sky-50" : "bg-white hover:bg-slate-50"}>
          <div className="flex items-start gap-2 px-4 py-4"><button type="button" onClick={() => selectStep(step.id)} className="min-w-0 flex-1 cursor-pointer text-left focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-blue-500"><strong className="block truncate text-sm text-slate-900">{step.name}</strong><span className="mt-1 block text-xs text-slate-600">{step.isSystem ? "網站停用時顯示" : funnelStepLabels[step.type]}</span></button>{!step.isSystem ? <div className="flex gap-1"><button type="button" aria-label={`上移 ${step.name}`} disabled={pending || index === 0} onClick={() => { const result = moveFunnelStepPage(content, step.id, Math.max(0, index - 1)); if (result.ok) persistContent(result.state, "步驟順序已儲存。"); }} className="min-h-11 min-w-11 cursor-pointer rounded p-1 text-slate-600 hover:bg-white disabled:opacity-30">↑</button><button type="button" aria-label={`移除 ${step.name}`} disabled={pending} onClick={() => { if (!window.confirm(`確定移除「${step.name}」及其頁面內容？`)) return; const result = removeFunnelStepPage(content, step.id); if (result.ok) persistContent(result.state, "步驟已移除。"); else setMessage(result.error); }} className="min-h-11 min-w-11 cursor-pointer rounded p-1 text-red-600 hover:bg-red-50">×</button></div> : <MoreHorizontal size={17} className="text-slate-400" />}</div>
        </article>)}</div>
        <button type="button" onClick={() => setAddOpen(true)} className="m-3 inline-flex min-h-11 cursor-pointer items-center justify-center gap-2 rounded-lg border border-slate-200 bg-white text-sm font-bold text-blue-700 transition-colors hover:bg-sky-50"><Plus size={17} />新增步驟</button>
        </div>
      </aside>
      <div className="min-w-0 overflow-auto">
        <nav aria-label="網站功能分頁" className="flex min-w-max border-b border-slate-200 px-4">{tabs.map((item) => <button type="button" key={item} disabled={item !== "Configuration" && secondaryDisabled} aria-pressed={tab === item} className={`cursor-pointer border-b-2 px-4 py-4 text-sm font-semibold transition-colors disabled:cursor-not-allowed disabled:text-slate-300 ${tab === item ? "border-sky-500 text-slate-950" : "border-transparent text-slate-600 hover:text-slate-900"}`} onClick={() => setTab(item)}>{funnelTabLabels[item]}</button>)}</nav>
        <div className="p-3 sm:p-7">
          {tab === "Configuration" ? <ConfigurationPanel active={active} content={content} editor={editor} templates={templates} selectedTemplateId={effectiveSelectedTemplateId} needsTemplate={needsTemplate} changeTemplate={changeTemplate} disabled={pending} setContent={(next) => { setContent(next); setDirty(true); }} setSelectedTemplateId={setSelectedTemplateId} setChangeTemplate={setChangeTemplate} onBlur={saveActiveMetadata} onApply={applyTemplate} navigate={navigate} /> : null}
          {tab === "Automation Rules" ? <FunnelAutomationSettings pageId={editor.pageId} csrfName={csrfName} csrfToken={csrfToken} /> : null}
          {tab !== "Configuration" && tab !== "Automation Rules" ? <fieldset disabled={pending} className="space-y-4"><legend className="mb-4 text-lg font-bold">{funnelTabLabels[tab]}</legend>{tab === "A/B test" ? <ExperimentSettings value={editor.operations.experiment} steps={editor.steps} onChange={(experiment) => operations({ ...editor.operations, experiment })} /> : null}{tab === "Deadline settings" ? <DeadlineSettings value={editor.operations.deadline} steps={editor.steps} onChange={(deadline) => operations({ ...editor.operations, deadline })} /> : null}{tab === "Stats" || tab === "Leads" || tab === "Sales" ? <ReportSettings tab={tab} editor={editor} reports={reports} reportError={reportError} retry={() => { setReports(null); setReportError(false); setReportRequest((value) => value + 1); }} onChange={operations} /> : null}<SettingsFooter pending={pending} dirty={dirty} save={saveSettings} reload={reload} /></fieldset> : null}
          {message ? <p role="status" className="mt-5 rounded-lg border border-blue-100 bg-blue-50 p-3 text-sm text-blue-900">{message}</p> : null}
        </div>
      </div>
    </div>
    {settingsOpen ? <div role="dialog" aria-modal="true" aria-labelledby="funnel-settings-title" className="fixed inset-0 z-[120] grid place-items-center bg-slate-950/60 p-4"><div className="max-h-[90dvh] w-full max-w-2xl overflow-auto rounded-2xl bg-white p-6 shadow-2xl"><div className="mb-5 flex items-start justify-between gap-4"><div><h2 id="funnel-settings-title" className="text-xl font-bold">網站設定</h2><p className="mt-1 text-sm text-slate-600">管理整個網站的名稱、網址與幣別。</p></div><button type="button" aria-label="關閉 網站設定" onClick={() => setSettingsOpen(false)} className="cursor-pointer rounded-lg p-2 hover:bg-slate-100"><X size={18} /></button></div><GlobalSettings editor={editor} change={change} /><SettingsFooter pending={pending} dirty={dirty} save={saveSettings} reload={reload} /></div></div> : null}
    {addOpen ? <AddStepDialog goal={content.flow.goal} name={newStepName} path={newStepPath} type={newStepType} source={newStepSource} templateId={effectiveNewTemplateId} templates={newTemplates} disabled={pending} onName={setNewStepName} onPath={setNewStepPath} onType={setNewStepType} onSource={setNewStepSource} onTemplate={setNewTemplateId} onClose={() => setAddOpen(false)} onSave={addStep} /> : null}
  </section>;
}

function ConfigurationPanel({ active, content, editor, templates, selectedTemplateId, needsTemplate, changeTemplate, disabled, setContent, setSelectedTemplateId, setChangeTemplate, onBlur, onApply, navigate }: { active: ReturnType<typeof getActiveFunnelStepPage>; content: FunnelStepPages; editor: FunnelOperationsEditor; templates: ReturnType<typeof listFunnelTemplateGallery>; selectedTemplateId: string; needsTemplate: boolean; changeTemplate: boolean; disabled: boolean; setContent: (next: FunnelStepPages) => void; setSelectedTemplateId: (id: string) => void; setChangeTemplate: (value: boolean) => void; onBlur: () => void; onApply: (id: string) => void; navigate: (href: string) => void }) {
  if (!active || active.step.isSystem) return <div className="grid min-h-[28rem] place-items-center rounded-xl border border-dashed border-slate-200 bg-slate-50 text-center"><div className="max-w-md p-8"><h2 className="text-xl font-bold text-slate-900">尚未建立網站步驟</h2><p className="mt-2 text-sm leading-6 text-slate-600">自訂流程會從空白開始。請使用左側的「新增步驟」 選擇頁面類型，再決定套用模板或從空白開始。</p></div></div>;
  if (needsTemplate || changeTemplate) return <div><div className="mb-5"><p className="text-xs font-bold uppercase tracking-wider text-blue-700">頁面設定</p><h2 className="mt-1 text-xl font-bold">為「{active.step.name}」選擇模板</h2><p className="mt-2 text-sm text-slate-600">模板已依 {funnelGoalLabels[content.flow.goal]} 與 {funnelStepLabels[active.step.type]} 過濾。完整預覽後再套用。</p></div>{templates.length ? <FunnelTemplateGalleryPicker templates={templates} selectedId={selectedTemplateId} disabled={disabled} onSelect={setSelectedTemplateId} onApply={onApply} /> : <div className="rounded-xl border border-dashed border-slate-300 bg-slate-50 p-6 text-sm text-slate-600">這個頁面類型 沒有相容模板。請新增步驟時選擇「從空白開始」。</div>}{changeTemplate ? <button type="button" onClick={() => setChangeTemplate(false)} className={`${button} mt-4`}>取消更換模板</button> : null}</div>;
  const nextName = (name: string) => { const result = renameFunnelStepPage(content, active.step.id, name); if (result.ok) setContent(result.state); };
  const nextPath = (path: string) => { const result = setFunnelStepPathPage(content, active.step.id, path); if (result.ok) setContent(result.state); };
  return <div><div className="mb-3 lg:mb-6"><p className="text-xs font-bold uppercase tracking-wider text-blue-700">頁面設定</p><h2 className="mt-1 text-xl font-bold text-slate-950">{active.step.name}</h2></div><div className="grid gap-5 xl:grid-cols-[minmax(0,1fr)_14rem]"><div className="space-y-5"><label className="grid gap-1.5 text-sm font-semibold text-slate-700">名稱 *<input className={control} value={active.step.name} disabled={disabled} onChange={(event) => nextName(event.currentTarget.value)} onBlur={onBlur} /></label><label className="grid gap-1.5 text-sm font-semibold text-slate-700">網址路徑 *<div className="flex min-h-10 overflow-hidden rounded-lg border border-slate-300 bg-white focus-within:border-blue-600 focus-within:ring-2 focus-within:ring-blue-100"><span className="flex items-center border-r border-slate-200 bg-slate-50 px-3 text-xs text-slate-600">/lp/{editor.slug}/</span><input aria-label="步驟 網址路徑" className="min-w-0 flex-1 px-3 text-sm outline-none" value={active.step.path} disabled={disabled} onChange={(event) => nextPath(event.currentTarget.value)} onBlur={onBlur} /></div></label><div className="border-t border-slate-200 pt-5"><p className="text-sm text-slate-600">模板：{active.step.template.templateId ? templates.find((item) => item.id === active.step.template.templateId)?.name ?? "已套用模板" : "從空白開始"}</p></div></div><div className="grid content-start gap-3"><Link href={`/lp/${editor.slug}/${active.step.path}`} target="_blank" className="inline-flex min-h-11 cursor-pointer items-center justify-center gap-2 rounded-lg bg-blue-700 px-4 text-sm font-bold text-white hover:bg-blue-800"><ExternalLink size={17} />查看步驟頁面</Link><button type="button" disabled={disabled} onClick={() => navigate(`/landing-pages/${editor.pageId}?step=${encodeURIComponent(active.step.id)}`)} className="inline-flex min-h-11 cursor-pointer items-center justify-center gap-2 rounded-lg bg-blue-700 px-4 text-sm font-bold text-white hover:bg-blue-800 disabled:cursor-not-allowed disabled:opacity-40"><Pencil size={17} />編輯頁面</button>{templates.length ? <button type="button" disabled={disabled} onClick={() => setChangeTemplate(true)} className="inline-flex min-h-11 cursor-pointer items-center justify-center gap-2 rounded-lg bg-blue-700 px-4 text-sm font-bold text-white hover:bg-blue-800 disabled:cursor-not-allowed disabled:opacity-40"><Settings size={17} />更換模板</button> : null}</div></div></div>;
}

function SettingsFooter({ pending, dirty, save, reload }: { pending: boolean; dirty: boolean; save: () => void; reload: () => void }) {
  return <div className="mt-6 flex flex-wrap items-center gap-3 border-t pt-4"><button type="button" disabled={pending || !dirty} className={`${button} border-blue-600 text-blue-700`} onClick={save}>儲存設定</button><button type="button" disabled={pending} className={button} onClick={reload}>重新載入</button><span className="text-sm text-slate-600">{pending ? "處理中…" : dirty ? "尚未儲存" : "已儲存"}</span></div>;
}

function AddStepDialog({ goal, name, path, type, source, templateId, templates, disabled, onName, onPath, onType, onSource, onTemplate, onClose, onSave }: { goal: FunnelStepPages["flow"]["goal"]; name: string; path: string; type: EditableStepType; source: "blank" | "template"; templateId: string; templates: ReturnType<typeof listFunnelTemplateGallery>; disabled: boolean; onName: (value: string) => void; onPath: (value: string) => void; onType: (value: EditableStepType) => void; onSource: (value: "blank" | "template") => void; onTemplate: (value: string) => void; onClose: () => void; onSave: () => void }) {
  const allowedGroups = stepTypeOptions.filter((group) => goal === "webinar" ? group.group === "Webinar" || group.group === "資訊" : group.group !== "Webinar");
  const canSave = Boolean(name.trim() && path.trim() && (source === "blank" || templateId));
  return <div role="dialog" aria-modal="true" aria-labelledby="add-step-title" className="fixed inset-0 z-[120] grid place-items-center bg-slate-950/60 p-4"><div className="max-h-[90dvh] w-full max-w-xl overflow-auto rounded-2xl bg-white p-6 shadow-2xl"><div className="mb-5 flex items-start justify-between gap-3"><div><h2 id="add-step-title" className="text-xl font-bold">新增步驟</h2><p className="mt-1 text-sm text-slate-600">選擇頁面類型與起始方式後一次建立，避免留下半完成步驟。</p></div><button type="button" aria-label="關閉新增步驟" onClick={onClose} className="cursor-pointer rounded-lg p-2 hover:bg-slate-100"><X size={18} /></button></div><div className="grid gap-4"><label className="grid gap-1 text-sm font-semibold">名稱 *<input className={control} value={name} onChange={(event) => onName(event.currentTarget.value)} /></label><label className="grid gap-1 text-sm font-semibold">網址路徑 *<input className={control} value={path} onChange={(event) => onPath(event.currentTarget.value.toLowerCase().replace(/[^a-z0-9-]/gu, ""))} /></label><label className="grid gap-1 text-sm font-semibold">類型 *<select className={control} value={type} onChange={(event) => onType(event.currentTarget.value as EditableStepType)}>{allowedGroups.map((group) => <optgroup key={group.group} label={group.group === "Webinar" ? "網路研討會" : group.group}>{group.items.map((item) => <option key={item.value} value={item.value}>{item.label}</option>)}</optgroup>)}</select></label><fieldset><legend className="text-sm font-semibold">起始內容 *</legend><div className="mt-2 grid gap-2 sm:grid-cols-2"><label className="flex cursor-pointer items-center gap-2 rounded-xl border border-slate-200 p-3"><input type="radio" checked={source === "template"} onChange={() => onSource("template")} />選擇模板</label><label className="flex cursor-pointer items-center gap-2 rounded-xl border border-slate-200 p-3"><input type="radio" checked={source === "blank"} onChange={() => onSource("blank")} />從空白開始</label></div></fieldset>{source === "template" ? <label className="grid gap-1 text-sm font-semibold">相容模板<select className={control} value={templateId} onChange={(event) => onTemplate(event.currentTarget.value)}><option value="">請選擇模板</option>{templates.map((template) => <option key={template.id} value={template.id}>{template.name}</option>)}</select>{templates.length === 0 ? <span className="font-normal text-amber-700">這個類型目前沒有模板，請改選從空白開始。</span> : null}</label> : null}</div><div className="mt-6 flex justify-end gap-2"><button type="button" onClick={onClose} className={button}>取消</button><button type="button" disabled={disabled || !canSave} onClick={onSave} className="min-h-10 cursor-pointer rounded-lg bg-blue-700 px-5 text-sm font-bold text-white hover:bg-blue-800 disabled:cursor-not-allowed disabled:opacity-40">儲存</button></div></div></div>;
}

function GlobalSettings({ editor, change }: { editor: FunnelOperationsEditor; change: (patch: Partial<SettingsState>) => void }) {
  return <div className="grid max-w-2xl gap-4">
    <label className="grid gap-1 text-sm">名稱<input className={control} value={editor.name} onChange={(event) => change({ name: event.target.value })} maxLength={160} /></label>
    <label className="grid gap-1 text-sm">網址名稱<input className={control} value={editor.slug} disabled={editor.status === "published"} onChange={(event) => change({ slug: event.target.value })} /><span className="text-slate-600">公開網址：/lp/{editor.slug}。已發布的網址名稱 須先取消發布才能修改。此設定不會綁定自訂網域。</span></label>
    <label className="grid gap-1 text-sm">幣別<select className={control} value={editor.currency} onChange={(event) => change({ currency: event.target.value })}>{["TWD", "USD", "EUR", "JPY", "HKD", "SGD"].map((currency) => <option key={currency}>{currency}</option>)}</select><span className="text-slate-600">須與商品幣別一致，不會換算既有價格或訂單。</span></label>
  </div>;
}

function StepSelect({ label, value, steps, disabled, onChange }: { label: string; value: string; steps: Steps; disabled?: boolean; onChange: (value: string) => void }) {
  return <label className="grid gap-1 text-sm">{label}<select className={control} value={value} disabled={disabled} onChange={(event) => onChange(event.target.value)}><option value="">請選擇步驟</option>{steps.map((step) => <option key={step.id} value={step.id}>{step.name} · {step.path}</option>)}</select></label>;
}

function ExperimentSettings({ value, steps, onChange }: { value: FunnelExperiment | null; steps: Steps; onChange: (value: FunnelExperiment | null) => void }) {
  const locked = Boolean(value && value.status !== "draft");
  function create() {
    onChange({ id: crypto.randomUUID(), status: "draft", controlStepId: steps[0]?.id ?? "", variantStepId: steps[1]?.id ?? "", controlWeight: 50, variantWeight: 50, winner: null });
  }
  if (!value) return <div className="space-y-3"><p>選擇已建立的兩個步驟作為對照組與測試組；先發布頁面再開始實驗。</p><button type="button" className={button} disabled={steps.length < 2} onClick={create}>建立 A/B 實驗</button></div>;
  return <div className="grid max-w-2xl gap-4">
    <p className="text-sm">實驗 {value.id} · 狀態：<strong>{experimentStatusLabels[value.status]}</strong>{value.winner ? ` · 勝出組別：${experimentArmLabels[value.winner]}` : ""}</p>
    <StepSelect label="對照組" value={value.controlStepId} steps={steps} disabled={locked} onChange={(controlStepId) => onChange({ ...value, controlStepId })} />
    <StepSelect label="測試組" value={value.variantStepId} steps={steps} disabled={locked} onChange={(variantStepId) => onChange({ ...value, variantStepId })} />
    <div className="grid grid-cols-2 gap-3">{(["control", "variant"] as const).map((arm) => <label key={arm} className="grid gap-1 text-sm">{arm === "control" ? "對照組權重" : "測試組權重"}<input className={control} type="number" min={0} max={100} disabled={locked} value={value[`${arm}Weight`]} onChange={(event) => onChange({ ...value, [`${arm}Weight`]: Number(event.target.value) })} /></label>)}</div>
    <p className={value.controlWeight + value.variantWeight !== 100 ? "text-red-700" : "text-slate-600"}>權重合計：{value.controlWeight + value.variantWeight} / 100。相同訪客在同一實驗維持相同組別；開始後配置鎖定。</p>
    <div className="flex flex-wrap gap-2">
      {value.status === "draft" ? <button type="button" className={button} onClick={() => onChange({ ...value, status: "running" })}>開始實驗</button> : null}
      {value.status === "running" ? <button type="button" className={button} onClick={() => onChange({ ...value, status: "stopped" })}>停止實驗</button> : null}
      {value.status === "running" || value.status === "stopped" ? (["control", "variant"] as const).map((winner) => <button type="button" key={winner} className={button} onClick={() => onChange({ ...value, status: "winner", winner })}>選定{experimentArmLabels[winner]}為勝出組別</button>) : null}
      {value.status === "stopped" || value.status === "winner" ? <button type="button" className={button} onClick={create}>建立新實驗</button> : null}
    </div><p className="text-sm text-slate-600">按「儲存設定」後生效。停止後回到對照組，選定勝出組別後會固定使用該組別。</p>
  </div>;
}

function DeadlineSettings({ value, steps, onChange }: { value: FunnelOperations["deadline"]; steps: Steps; onChange: (value: FunnelOperations["deadline"]) => void }) {
  let local = "尚未設定";
  try { if (value.expiresAt) local = new Intl.DateTimeFormat("zh-TW", { dateStyle: "full", timeStyle: "long", timeZone: value.timezone }).format(new Date(value.expiresAt)); } catch { local = "時間或時區無效"; }
  return <div className="grid max-w-2xl gap-4">
    <label className="flex items-center gap-2"><input type="checkbox" checked={value.enabled} onChange={(event) => onChange({ ...value, enabled: event.target.checked })} />啟用截止時間</label>
    <label className="grid gap-1 text-sm">時區<input className={control} value={value.timezone} onChange={(event) => onChange({ ...value, timezone: event.target.value })} placeholder="Asia/Taipei" /></label>
    <label className="grid gap-1 text-sm">截止時間（含時區偏移）<input className={control} value={value.expiresAt ?? ""} onChange={(event) => onChange({ ...value, expiresAt: event.target.value || null })} placeholder="2026-12-31T23:59:00+08:00" /><span className="text-slate-600">例如 2026-12-31T23:59:00+08:00；採夏令時間的地區請明確填入當時的時區偏移。</span></label>
    {/* ICU punctuation can differ between Node and Chromium even with the same
        locale/time zone. The persisted ISO value remains the source of truth. */}
    <p className="text-sm" suppressHydrationWarning>指定時區顯示：{local}</p>
    <label className="grid gap-1 text-sm">截止行為<select className={control} value={value.behavior} onChange={(event) => onChange({ ...value, behavior: event.target.value as "closed" | "redirect" })}><option value="closed">顯示已截止</option><option value="redirect">導向指定步驟</option></select></label>
    {value.behavior === "redirect" ? <label className="grid gap-1 text-sm">到期導向<select className={control} value={value.redirectPath} onChange={(event) => onChange({ ...value, redirectPath: event.target.value })}><option value="">請選擇已發布步驟</option>{steps.slice(1).map((step) => <option key={step.id} value={step.path}>{step.name} · {step.path}</option>)}</select></label> : null}
    <p className="text-sm text-slate-600">截止瞬間即生效，公開頁及提交／結帳均由伺服器判定。到期導向頁可繼續閱讀，不能繼續提交或結帳。</p>
  </div>;
}

function ReportSettings({ tab, editor, reports, reportError, retry, onChange }: { tab: "Stats" | "Leads" | "Sales"; editor: FunnelOperationsEditor; reports: FunnelReports | null; reportError: boolean; retry: () => void; onChange: (operations: FunnelOperations) => void }) {
  const key = tab.toLowerCase() as "stats" | "leads" | "sales";
  const filter = editor.operations.reports[key];
  function change(patch: Partial<typeof filter>) { onChange({ ...editor.operations, reports: { ...editor.operations.reports, [key]: { ...filter, ...patch } } }); }
  return <div className="space-y-4">
    <div className="flex flex-wrap gap-3"><label className="grid gap-1 text-sm">報表步驟<select className={control} value={filter.stepId} onChange={(event) => change({ stepId: event.target.value })}><option value="">全部步驟</option>{editor.steps.map((step) => <option key={step.id} value={step.id}>{step.name}</option>)}</select></label><label className="grid gap-1 text-sm">最近天數<input className={control} type="number" min={1} max={90} value={filter.days} onChange={(event) => change({ days: Number(event.target.value) })} /></label></div>
    <p className="text-sm text-slate-600">儲存後套用篩選條件。來源紀錄唯讀。{reports ? `以下為已儲存條件的結果，更新時間：${reports.generatedAt}。` : null}</p>
    {reports ? tab === "Stats" ? <StatsReport reports={reports} /> : tab === "Leads" ? <LeadsReport reports={reports} editor={editor} /> : <SalesReport reports={reports} editor={editor} /> : reportError ? <p role="alert">報表暫時無法載入。<button type="button" className="ml-2 underline" onClick={retry}>重試</button></p> : <p role="status">報表載入中…</p>}
  </div>;
}
function StatsReport({ reports }: { reports: FunnelReports }) {
  return <div className="overflow-auto"><p className="mb-3 text-sm">瀏覽次數為伺服器公開頁交付紀錄，包含重新整理；步驟轉換為同一匿名訪客依序到達下一步，非成交。未取得匿名識別的瀏覽不計入。</p>{reports.statsTruncated ? <p role="alert">已達 10,000 筆上限，以下為部分資料，請縮短日期範圍。</p> : null}
    <table className="w-full text-left text-sm"><thead><tr>{["步驟", "瀏覽次數", "訪客", "報名次數", "步驟轉換", "流失人數"].map((label) => <th key={label} className="p-2">{label}</th>)}</tr></thead><tbody>{reports.stats.map((row) => <tr key={row.stepId} className="border-t"><td className="p-2">{row.name}</td><td>{row.pageViews}</td><td>{row.visitors}</td><td>{row.submissions}</td><td>{row.conversionRate === null ? "—" : `${(row.conversionRate * 100).toFixed(1)}% (${row.conversions})`}</td><td>{row.dropOff ?? "—"}</td></tr>)}</tbody></table>
    <div className="mt-4">{reports.experiments.map((row) => <p key={`${row.id}-${row.arm}`} className="text-sm">實驗 {row.id} · {row.arm === "control" || row.arm === "variant" ? experimentArmLabels[row.arm] : "未知組別"} · 瀏覽次數 {row.pageViews} · 報名次數 {row.submissions}</p>)}</div>
    <details className="mt-4"><summary>檢視來源事件編號（前 20 筆）</summary>{reports.sources.map((source) => <p key={source.id} className="break-all font-mono text-xs">{source.id} · {source.stepId} · {source.createdAt}</p>)}</details>
  </div>;
}
function LeadsReport({ reports, editor }: { reports: FunnelReports; editor: FunnelOperationsEditor }) {
  return <div className="overflow-auto"><p className="mb-3 text-sm">只列出伺服器驗證網站來源後建立的提交紀錄；不顯示姓名、Email、電話或表單答案。</p>{reports.leadsTruncated ? <p role="alert">顯示最新 100 筆，請縮短日期或選擇步驟。</p> : null}<table className="w-full text-left text-sm"><thead><tr>{["網站", "步驟", "時間", "報名編號", "驗證狀態"].map((label) => <th className="p-2" key={label}>{label}</th>)}</tr></thead><tbody>{reports.leads.map((row) => <tr className="border-t" key={row.id}><td className="p-2">{editor.name}</td><td>{editor.steps.find((step) => step.id === row.stepId)?.name ?? "無法辨識的步驟"}</td><td>{row.createdAt}</td><td className="font-mono">{row.submissionId}</td><td>{reportStatusLabel(row.verificationStatus, "verification")}</td></tr>)}</tbody></table>{!reports.leads.length ? <p className="p-3">此範圍尚無可信提交紀錄。</p> : null}</div>;
}
function SalesReport({ reports, editor }: { reports: FunnelReports; editor: FunnelOperationsEditor }) {
  return <div className="overflow-auto"><p className="mb-3 text-sm">來源為訂單與付款紀錄的已付款資料，排除測試訂單；退款另列，不將不同幣別相加。</p>{reports.salesTruncated ? <p role="alert">顯示最新 100 筆，請縮短日期或選擇步驟。</p> : null}<table className="w-full text-left text-sm"><thead><tr>{["訂單", "步驟", "付款時間", "幣別", "已付／退款（分）", "訂單／付款狀態", "付款編號"].map((label) => <th className="p-2" key={label}>{label}</th>)}</tr></thead><tbody>{reports.sales.map((row) => <tr className="border-t" key={row.id}><td className="p-2"><span>{row.orderNumber}</span><small className="block">{row.id}</small></td><td>{editor.steps.find((step) => step.id === row.stepId)?.name ?? "無法辨識的步驟"}</td><td>{row.paidAt}</td><td>{row.currency}</td><td>{row.paidAmountCents} / {row.refundedAmountCents}</td><td>{reportStatusLabel(row.status, "order")} / {reportStatusLabel(row.paymentStatus, "payment")}</td><td className="font-mono">{row.paymentId}</td></tr>)}</tbody></table>{!reports.sales.length ? <p className="p-3">此範圍尚無已付款訂單。</p> : null}</div>;
}
